namespace Atc.XamlToolkit.SourceGenerators.Tests.Generators;

[SuppressMessage("Design", "MA0048:File name must match type name", Justification = "OK.")]
public sealed partial class FrameworkElementGeneratorTests
{
    [Fact]
    public void DefaultStyleKey_Wpf_GeneratesStaticConstructor()
    {
        const string inputCode =
            """
            namespace TestNamespace;

            [DefaultStyleKey]
            public partial class MyControl : Control
            {
            }
            """;

        const string expectedCode =
            """
            // <auto-generated>
            #nullable enable
            using System.Windows;

            namespace TestNamespace;

            public partial class MyControl
            {
                static MyControl()
                {
                    DefaultStyleKeyProperty.OverrideMetadata(
                        typeof(MyControl),
                        new FrameworkPropertyMetadata(typeof(MyControl)));
                }
            }

            #nullable disable
            """;

        var generatorResult = RunGenerator<FrameworkElementGenerator>(inputCode);

        AssertGeneratorRunResultAsEqual(expectedCode, generatorResult);
        AssertGeneratorRunResultHasDiagnostics([], generatorResult);
    }

    [Theory]
    [InlineData("[Atc.XamlToolkit.Controls.Attributes.DefaultStyleKey]")]
    [InlineData("[global::Atc.XamlToolkit.Controls.Attributes.DefaultStyleKeyAttribute]")]
    public void DefaultStyleKey_Wpf_AttributeWrittenFullyQualified_IsRecognised(
        string attribute)
    {
        var inputCode =
            $$"""
            namespace TestNamespace;

            {{attribute}}
            public partial class MyControl : Control
            {
            }
            """;

        var generatorResult = RunGenerator<FrameworkElementGenerator>(inputCode);

        var generatedCode = Assert.Single(generatorResult.GeneratorResult.GeneratedSources).SourceText.ToString();
        Assert.Contains("static MyControl()", generatedCode, StringComparison.Ordinal);
    }

    [Fact]
    public void DefaultStyleKey_Wpf_WithStyleType_UsesThatType()
    {
        const string inputCode =
            """
            namespace TestNamespace;

            [DefaultStyleKey(typeof(Button))]
            public partial class MyButton : Button
            {
            }
            """;

        const string expectedCode =
            """
            // <auto-generated>
            #nullable enable
            using System.Windows;

            namespace TestNamespace;

            public partial class MyButton
            {
                static MyButton()
                {
                    DefaultStyleKeyProperty.OverrideMetadata(
                        typeof(MyButton),
                        new FrameworkPropertyMetadata(typeof(Button)));
                }
            }

            #nullable disable
            """;

        var generatorResult = RunGenerator<FrameworkElementGenerator>(inputCode);

        AssertGeneratorRunResultAsEqual(expectedCode, generatorResult);
    }

    [Fact]
    public void DefaultStyleKey_Wpf_TogetherWithDependencyProperty_GeneratesBoth()
    {
        const string inputCode =
            """
            namespace TestNamespace;

            [DefaultStyleKey]
            public partial class MyControl : Control
            {
                [DependencyProperty]
                private bool isActive;
            }
            """;

        const string expectedCode =
            """
            // <auto-generated>
            #nullable enable
            using System.Windows;

            namespace TestNamespace;

            public partial class MyControl
            {
                static MyControl()
                {
                    DefaultStyleKeyProperty.OverrideMetadata(
                        typeof(MyControl),
                        new FrameworkPropertyMetadata(typeof(MyControl)));
                }

                public static readonly DependencyProperty IsActiveProperty = DependencyProperty.Register(
                    nameof(IsActive),
                    typeof(bool),
                    typeof(MyControl),
                    new PropertyMetadata(defaultValue: Atc.XamlToolkit.BooleanBoxes.FalseBox));

                public bool IsActive
                {
                    get => (bool)GetValue(IsActiveProperty);
                    set => SetValue(IsActiveProperty, Atc.XamlToolkit.BooleanBoxes.Box(value));
                }
            }

            #nullable disable
            """;

        var generatorResult = RunGenerator<FrameworkElementGenerator>(inputCode);

        AssertGeneratorRunResultAsEqual(expectedCode, generatorResult);
    }

    [Fact]
    public void DefaultStyleKey_Wpf_ClassWithItsOwnStaticConstructor_GeneratesAMethodToCall()
    {
        // A class can only have one static constructor, so the override is generated
        // as a method for the hand-written constructor to call.
        const string inputCode =
            """
            namespace TestNamespace;

            [DefaultStyleKey]
            public partial class MyControl : Control
            {
                static MyControl()
                {
                    OverrideDefaultStyleKey();
                    FocusableProperty.OverrideMetadata(typeof(MyControl), new FrameworkPropertyMetadata(false));
                }
            }
            """;

        const string expectedCode =
            """
            // <auto-generated>
            #nullable enable
            using System.Windows;

            namespace TestNamespace;

            public partial class MyControl
            {
                /// <summary>
                /// Makes this type its own default style key. Call it from the static constructor.
                /// </summary>
                private static void OverrideDefaultStyleKey()
                    => DefaultStyleKeyProperty.OverrideMetadata(
                        typeof(MyControl),
                        new FrameworkPropertyMetadata(typeof(MyControl)));
            }

            #nullable disable
            """;

        var generatorResult = RunGenerator<FrameworkElementGenerator>(inputCode);

        AssertGeneratorRunResultAsEqual(expectedCode, generatorResult);
        AssertGeneratorRunResultHasDiagnostics([], generatorResult);
    }

    [Fact]
    public void DefaultStyleKey_Wpf_OwnStaticConstructorThatDoesNotCallTheMethod_ReportsDiagnostic()
    {
        const string inputCode =
            """
            namespace TestNamespace;

            [DefaultStyleKey]
            public partial class MyControl : Control
            {
