        var generatorResult = RunGenerator<FrameworkElementGenerator>(inputCode);

        AssertGeneratorRunResultHasDiagnostics(["AtcXamlToolkit0011"], generatorResult);
    }

    [Fact]
    public void DefaultStyleKey_Avalonia_GeneratesStyleKeyOverride_ThatCompiles()
    {
        const string inputCode =
            """
            using Atc.XamlToolkit.Controls.Attributes;
            using Avalonia.Controls;
            using Avalonia.Controls.Primitives;

            namespace TestNamespace;

            [DefaultStyleKey]
            public partial class MyControl : TemplatedControl
            {
                public System.Type ExposedStyleKey => StyleKeyOverride;
            }

            [DefaultStyleKey(typeof(Button))]
            public partial class MyButton : Button
            {
                public System.Type ExposedStyleKey => StyleKeyOverride;
            }
            """;

        AssertCompilesWithAllGenerators(inputCode);

        var generatedCode = string.Join(
            Environment.NewLine,
            GetSourcesGeneratedForAvaloniaConsumer(inputCode));

        Assert.Contains("protected override global::System.Type StyleKeyOverride => typeof(MyControl);", generatedCode, StringComparison.Ordinal);
        Assert.Contains("protected override global::System.Type StyleKeyOverride => typeof(Button);", generatedCode, StringComparison.Ordinal);
    }
}